Kavita Gateway.GATEWAY_CONFIG:
{
  admin off
}
:8080 {
  handle /healthz {
    rewrite * /api/health
    reverse_proxy http://__KAVITA__
  }
  @register path /api/account/register /api/account/register/*
  handle @register {
    basic_auth {
      __USERNAME__ __PASSWORD_HASH__
    }
    reverse_proxy http://__KAVITA__ {
      header_up -Authorization
      header_up X-Forwarded-Proto {http.request.header.X-Forwarded-Proto}
    }
  }
  handle /files* {
    basic_auth {
      __USERNAME__ __PASSWORD_HASH__
    }
    reverse_proxy http://__UPLOADS__ {
      header_up -Authorization
    }
  }
  handle {
    reverse_proxy http://__KAVITA__ {
      header_up X-Forwarded-Proto {http.request.header.X-Forwarded-Proto}
    }
  }
}
